//! JS/TS generated-source detection by path and leading header.

use globset::GlobSet;
use std::path::Path;
use std::sync::OnceLock;

const GENERATED_PATHS: &[&str] = &[
    "**/_generated/**",
    "**/__generated__/**",
    "**/*.gen.*",
    "**/*.generated.*",
];

const HEADER_MARKERS: &[&str] = &[
    "@generated",
    "auto-generated",
    "automatically generated",
    "code generated by",
];

const HEADER_BYTES: usize = 1024;

pub(crate) fn is_generated(path: &Path, src: &[u8]) -> bool {
    static PATHS: OnceLock<GlobSet> = OnceLock::new();
    PATHS
        .get_or_init(|| crate::profiles::compile_profile_globs(GENERATED_PATHS))
        .is_match(path)
        || has_generated_header(src)
}

fn has_generated_header(src: &[u8]) -> bool {
    let head = String::from_utf8_lossy(&src[..src.len().min(HEADER_BYTES)]).to_ascii_lowercase();
    HEADER_MARKERS.iter().any(|marker| head.contains(marker))
        || head
            .lines()
            .any(|line| line.contains("do not edit") && line.contains("generated"))
}

#[cfg(test)]
mod tests {
    use super::is_generated;
    use std::path::Path;

    #[test]
    fn generated_paths_and_headers_are_detected() {
        let plain = b"export const a = 1;\n";
        assert!(is_generated(Path::new("src/_generated/api.ts"), plain));
        assert!(is_generated(Path::new("src/__generated__/q.ts"), plain));
        assert!(is_generated(Path::new("src/routes.gen.ts"), plain));
        assert!(is_generated(Path::new("src/schema.generated.js"), plain));
        assert!(is_generated(
            Path::new("src/api.ts"),
            b"/* @generated by codegen */\nexport const a = 1;\n"
        ));
        assert!(is_generated(
            Path::new("src/api.ts"),
            b"// This file was automatically generated. DO NOT EDIT.\n"
        ));
        assert!(!is_generated(Path::new("src/regen.ts"), plain));
        assert!(!is_generated(Path::new("src/generator.ts"), plain));
    }

    #[test]
    fn do_not_edit_without_a_generation_phrase_is_hand_written() {
        let src = b"export const a = 1;\n// Do not edit this list without asking the owners.\nexport const owners = [];\n";
        assert!(!is_generated(Path::new("src/owners.ts"), src));
    }

    #[test]
    fn do_not_edit_beside_generated_marks_the_file() {
        let src = b"// DO NOT EDIT: generated from schema.json\nexport const a = 1;\n";
        assert!(is_generated(Path::new("src/schema.ts"), src));
    }

    #[test]
    fn markers_past_the_header_window_are_ignored() {
        let mut src = "export const a = 1;\n".repeat(80).into_bytes();
        src.extend_from_slice(b"// @generated\n");
        assert!(!is_generated(Path::new("src/api.ts"), &src));
    }
}
